compile.workshop:
variables {
    global:
        0: value
}

rule ("issue 28 syntax") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(value, 1);
        Loop If(Not(Array Contains(Array(2, 3), Global.value)));
        If(True);
            Skip(Value In Array(Array(2, 0, 1), Add(1, Index Of Array Value(Array(16, 0X20), Global.value))));
        //__label_switch_2_0__:
        Set Global Variable(value, True);
        //__label_switch_2_1__:
        Set Global Variable(value, Mapped Array(Array(1, 2), Multiply(Current Array Element, 2)));
        //__label_switch_2_default__:
        Set Global Variable(value, 1);
        End;
        Set Global Variable(value, Sorted Array(Array(1, 2), Current Array Element));
        Set Global Variable(value, Custom String("formatted 0"));
        Set Global Variable(value, Custom String("ｗｉｄｅ"));
    }
}

